// Authored teaching cases, not recorded model outputs or customer experiences.
const section=(id,title,body)=>[id,title,body];
const table=(heads,rows)=>`<div class="data-wrap"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const dl=(file,label)=>`<p><a href="../downloads/${file}" download>${label} ↓</a></p>`;
const link=(file,label)=>`<p><a href="${file}.html">${label} ↗</a></p>`;
const c=(slug,title,description,category,sections,sources=[])=>({slug,title,description,category,sections,sources});
const risk=['NIST: AI risks and trustworthiness','https://airc.nist.gov/airmf-resources/airmf/3-sec-characteristics/'];
const gen=['NIST: Generative AI Profile (PDF), section 2.2','https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.600-1.pdf'];
export const caseDownloads={
 'support-triage.csv':`ticket_id,message,expected_queues\nT01,Please refund my unused order.,Refund\nT02,The mug arrived broken.,Replacement\nT03,I was charged twice and my parcel is missing.,Billing + Delivery\nT04,What time do you close?,Information\nT05,Do not refund this order; please replace the broken item.,Replacement\nT06,The problem is back.,Needs clarification\n`,
 'meeting-source.txt':`FICTIONAL PRACTICE NOTES — not a real meeting or recording.\nMeeting date: 9 November 2026.\nMira: Use the new order export for next week's report.\nDan: I will confirm by 11 November whether discounts are per line.\nMira: Someone should check the repeated order.\nDan: We might switch suppliers if the problem continues.\nMira: Discuss again Friday.\nNo further attendance, ownership, deadline or supplier decision is supplied.\n`,
 'meeting-actions.csv':`source_statement,type,action_or_decision,owner,due_date,needs_confirmation\nUse the new order export for next week's report.,Decision,Use new export,,,Which reporting week\nI will confirm by 11 November whether discounts are per line.,Action,Confirm discount meaning,Dan,2026-11-11,\nSomeone should check the repeated order.,Unassigned action,Review repeated order,,,Owner and deadline\nWe might switch suppliers if the problem continues.,Proposal,Possible supplier change,,,No decision recorded\nDiscuss again Friday.,Follow-up,Discuss again,,,Confirm calendar date\n`,
 'email-brief.txt':`FICTIONAL PRACTICE BRIEF — no actual customer data.\nPurpose: update a customer about a delayed parcel.\nVerified fact: the carrier estimates delivery on 20 November 2026.\nUncertainty: the estimate is not guaranteed.\nAuthority: the writer may offer a status update, but may not promise refunds or compensation.\nUnknowns: customer name and order reference. Keep placeholders.\nOutput: at most 90 words; calm, specific and ready for a person to review.\n`,
 'policy-source.txt':`FICTIONAL POLICY PACK — teaching material, not employment or legal advice.\nP1 — Archived visitor policy, effective 1 January 2025, superseded 1 October 2026.\nVisitors may enter the office between 09:00 and 18:00.\nP2 — Current visitor policy, effective 1 October 2026.\nVisitors may enter between 10:00 and 16:00 and must have a named host.\nContractors working on an approved maintenance visit may enter from 08:00 with facilities approval.\nP3 — Cafeteria information, current.\nThe cafeteria opens at 08:00. This does not grant building access.\nQuestion date: 13 November 2026.\nNo weekend rule or host-approval procedure is supplied.\n`,
 'claim-audit.txt':`AUTHORED PRACTICE DRAFT — not a recorded AI response.\nDraft: Our weekly report proves sales grew 18%. Nine orders produced RM267.60, and all customer identifiers were preserved.\nAvailable evidence: The site's fictional weekly-sales workbook contains nine included lines across eight distinct orders, 26 units and RM267.60 net shipped sales for 26 October through 1 November 2026.\nNo prior-period total is supplied.\nIdentifier preservation requires inspecting stored values; a displayed report total alone cannot prove it.\nTask: classify each draft claim as supported, contradicted or unestablished, then rewrite only from supported facts.\n`
};
export const aiCases=[
 c('what-is-artificial-intelligence','What AI changes in a support-ticket workflow','Compare a keyword rule with a proposed AI classifier using six fictional tickets and an answer key.','AI concepts',[
 section('task','Start with six tickets you can inspect',`<p>Artificial intelligence covers systems that infer outputs such as predictions, labels or generated text from inputs. For a small support queue, the useful question is which messages reach the right people. This case separates a simple keyword rule from a proposed classifier without pretending to have benchmarked an AI product.</p>${dl('support-triage.csv','Six tickets and the intended routing')}<p>Hide the expected_queues column before testing a classifier. It is an answer key for this exercise, not an input feature. Every message is fictional.</p>`),
 section('rule','Trace the rule before replacing it',`<p>Consider the rule “route messages containing refund to Refund.” It sends T01 correctly, but also sends T05 to Refund even though the customer explicitly asks for a replacement. It misses the damaged mug in T02. T03 requires both Billing and Delivery; a single-label design loses part of the request.</p>${table(['Ticket','Important evidence','Expected handling'],[['T02','Mug arrived broken','Replacement'],['T03','Charged twice; parcel missing','Billing + Delivery'],['T05','Do not refund; replace','Replacement'],['T06','No specific problem','Ask for clarification']])}`),
 section('test','Give the proposed classifier a fair test',`<p>Ask for zero or more queue labels, the source words supporting each label, and Needs clarification when the request is insufficient. Score the routing against the answer key. A plausible explanation cannot compensate for a missed billing issue. Record the exact prompt, product, model if shown, test date and full output.</p><p>Six cases reveal particular failures; they cannot estimate production accuracy. A deployment decision needs representative messages, edge cases, workload costs and a review process. Keep real customer information in approved systems.</p>`),
 section('decision','Choose the smallest useful change',`<p>If the queue needs only a reliable refund keyword alert, a corrected rule may be enough. If paraphrases and multiple issues matter, evaluate a classifier. Keep uncertain requests visible for a person. The output of this exercise is a routing test and a decision record, rather than a general claim that AI understands customers.</p>${link('what-ai-is-good-at-and-bad-at','Decide which parts of the workflow to automate')}`)
 ],[risk]),
 c('what-is-generative-ai','What generative AI adds to an email draft','Use one fictional delivery brief to separate supplied facts, generated wording, and promises requiring approval.','AI concepts',[
 section('brief','The input is a brief, not a private thread',`<p>Generative AI produces content such as text or images from an input. In an email workflow, its useful contribution can be wording and organization. Whether the parcel will arrive is a separate question requiring evidence from the carrier.</p>${dl('email-brief.txt','Download the fictional delivery brief')}<p>The brief supplies an estimated delivery date of 20 November 2026. It does not supply the customer's name, an order number, a guaranteed arrival, or permission to promise compensation.</p>`),
 section('draft','Create a draft with explicit boundaries',`<p>An authored prompt for this exercise is: “Use only the attached fictional brief. Write a calm update of at most 90 words. Keep name and order-reference placeholders. Describe 20 November as the carrier's estimate. Do not promise a refund, compensation or guaranteed delivery.” This is a teaching prompt, not a record of a model test.</p><blockquote><p>Hello [name], I’m writing about order [reference]. The carrier currently estimates delivery on 20 November 2026. This is an estimate, and the date may change. I’m sorry for the delay. Please contact us if you need a further status update.</p></blockquote><p>The paragraph above is an authored acceptable answer. It shows one possible outcome rather than predicting what any assistant will generate.</p>`),
 section('review','Separate wording from new facts',`${table(['Draft element','Where it comes from','Review decision'],[['Delivery estimate','Supplied brief','Retain the uncertainty'],['Greeting and apology','Authored wording','Check tone'],['Guaranteed arrival','No evidence','Remove'],['Refund offer','No authority supplied','Remove or obtain approval'],['Customer name','Not supplied','Keep a placeholder']])}<p>A shorter draft is not necessarily better if it drops the word estimate. A warmer draft is not acceptable if it invents a compensation offer. Judge the final message against the brief, then review it before sending.</p>`),
 section('reuse','Reuse the specification, not the customer record',`<p>Keep the purpose, factual fields and approval limits as a reusable brief. Replace facts for each case. Do not copy yesterday's estimate into today's message. For higher-stakes communication, the person responsible must verify the actual facts and authorization.</p>${link('give-ai-feedback-that-improves-drafts','Revise a draft against a factual checklist')}`)
 ],[gen]),
 c('large-language-models-explained','Why an LLM can write a fluent but unsupported answer','Trace a visitor-policy question through source text, missing evidence, and a checkable answer.','AI concepts',[
 section('example','A fluent answer can use the wrong rule',`<p>A large language model generates text using learned patterns and the context supplied to it. That makes it useful for explaining and rewriting text, but a convincing sentence alone does not establish which policy applies. Use the fictional policy pack to inspect that difference.</p>${dl('policy-source.txt','Download the policy pack')}<p>The question is: “Can an ordinary visitor enter at 09:00 on 13 November 2026?” P1 says 09:00, but is archived. Current P2 starts ordinary visits at 10:00 and requires a named host. The 08:00 maintenance exception has separate conditions.</p>`),
 section('answer','An answer should identify its evidence',`<p>An authored correct answer is: “Under P2, ordinary visitor access starts at 10:00 and requires a named host, so 09:00 is outside that window. P1 is superseded. The maintenance exception requires an approved maintenance visit and facilities approval.” Each factual part points to a supplied source.</p><p>An answer that says 09:00 because P1 was retrieved has selected a real sentence with the wrong status. An answer that grants access because the cafeteria opens at 08:00 confuses two different permissions. Neither failure requires invented words.</p>`),
 section('context','Ask for gaps as well as answers',`<p>Try a second question: “Can a visitor enter on Sunday?” The pack gives no weekend rule. The acceptable result is that the supplied material does not establish Sunday access. Asking for a confident yes or no would hide the missing information.</p><p>Useful prompt fields are the question date, allowed source IDs, document status and required quotation or section reference. Those fields help a reviewer; they cannot guarantee that a model selects the right evidence.</p>`),
 section('limits','Keep the scope of the exercise clear',`<p>This is an authored reasoning case, not an observed failure rate for any model. Product context limits, tools and retrieval features vary. For real access decisions, check the authoritative policy and ask its owner about omissions. Use this pack to practice distinguishing supported, contradicted and unestablished claims.</p>${link('rag-explained-plain-english','See where retrieval can introduce the wrong source')}`)
 ],[gen]),
 c('rag-explained-plain-english','RAG explained with a policy retrieval failure','Follow a fictional source from search result to answer, including an archived rule and an unrelated opening time.','AI concepts',[
 section('pipeline','Retrieval and generation are separate steps',`<p>Retrieval-augmented generation supplies retrieved material to a model as context for an answer. It can make a source available that was not already in the conversation. The retrieved item still needs the right scope, date and permissions.</p>${dl('policy-source.txt','Use the three-document policy pack')}<p>Imagine a search for office opening time returns P1 and P3. P1 is archived; P3 concerns the cafeteria. An assistant can cite both faithfully and still answer the visitor-access question incorrectly.</p>`),
 section('trace','Trace the failure through the system',`${table(['Stage','Failure in this case','Observable check'],[['Source collection','P1 remains searchable','Keep archived status and effective dates'],['Retrieval','P2 not selected','Check retrieved source IDs'],['Answer','Cafeteria time becomes access permission','Compare each claim with source scope'],['Review','Citation treated as proof','Open the cited passage and inspect exceptions']])}<p>The correct ordinary-visitor window for the supplied question date is 10:00–16:00 with a named host. The maintenance exception is conditional. A weekend answer remains unresolved because the pack does not contain that rule.</p>`),
 section('test','Test a small set of different questions',`<p>Use one question answered directly by P2, one requiring its exception, one where P1 conflicts, and one with no answer in the pack. Record which passages were retrieved, not just the final wording. That separates a retrieval miss from a generation error.</p><p>Do not solve a missing-source problem by asking the assistant to be more confident. Correct the source collection or retrieval conditions, then rerun the same cases. Preserve a failed attempt so the change can be assessed.</p>`),
 section('scope','Keep access controls with the documents',`<p>A real deployment also needs to preserve who may retrieve each source. This fictional pack is public teaching data and tests no permissions. It cannot certify a workplace search system. For a small one-off task, manually supplying the correct current excerpt may be enough.</p>${link('source-first-ai-research-workflow','Build a source ledger before drafting')}`)
 ],[['Original RAG research paper','https://arxiv.org/abs/2005.11401']]),
 c('ai-agents-explained','Where an AI agent needs a stop in an order workflow','Map reading, drafting, editing, and sending to different permissions using a fictional delayed order.','AI concepts',[
 section('workflow','A suggested next step is different from an executed action',`<p>For this case, an agent is a system that can choose and use tools while working toward a task. The important distinction is what it can change. An assistant that drafts an update needs different access from one that modifies an order or sends the message.</p>${dl('email-brief.txt','Start with the fictional delayed-order brief')}<p>The task is to prepare a customer update using a carrier estimate. It does not authorize compensation, changing delivery details or contacting a different customer.</p>`),
 section('permissions','Give each step an observable boundary',`${table(['Step','Required capability','Completion evidence'],[['Read the estimate','Read carrier status','Source and observation time recorded'],['Draft the update','Create unsent text','Draft matches the brief'],['Change the address','Modify order','Stop: outside this task'],['Send email','Contact the customer','Correct recipient, approved draft and explicit send authorization']])}<p>Write these limits before connecting tools. “Handle the delay” is too ambiguous to establish whether refunds or record changes are allowed.</p>`),
 section('failure','Prevent retries from creating extra actions',`<p>Suppose a send tool times out. The system should inspect the send record before trying again. A timeout does not prove that delivery failed. Repeating the action without checking may send duplicate messages. For a real integration, define a unique operation identifier and a way to reconcile the result.</p><p>A webpage or carrier note might contain instructions. Treat them as information about the parcel, not as authority to expand the task. Keep tool permissions narrower than the full power of the user account where possible.</p>`),
 section('trial','Rehearse with unsent drafts first',`<p>Test an ordinary case, an absent estimate, a conflicting order reference and an uncertain send result. An acceptable run stops when it cannot establish the facts or action outcome. This article is a design exercise; no autonomous agent or messaging service was deployed or benchmarked here.</p>${link('small-team-ai-policy-that-people-follow','Write task-specific team permissions')}`)
 ]),
 c('what-ai-is-good-at-and-bad-at','Choose AI tasks by the cost of checking the answer','Apply a four-question decision to ticket routing, email drafting, sales arithmetic, and order changes.','Task choice',[
 section('decision','Decide at the step level',`<p>A workflow can contain both useful drafting tasks and actions that deserve strict controls. Rather than label all email or spreadsheet work suitable for AI, separate the input, proposed output, available check and consequence of error. The examples below are fictional task decisions, not product performance measurements.</p>${table(['Task','Independent check','Suggested starting point'],[['Rewrite a delay update','Compare with a short verified brief','Draft, then review'],['Route a vague ticket','No clear intent in the message','Ask for clarification'],['Calculate weekly sales','Known-answer workbook and totals','Use formulas or a deterministic tool'],['Change delivery address','Identity and authorization checks','Use the approved order process']])}`),
 section('questions','Ask four concrete questions',`<p>First, what data is actually needed? A tone edit needs a brief, not the full customer history. Second, what would count as a correct output? For the sales sample it is a defined date window, status and exact total. Third, how will a person check the result? Fourth, what happens if the check misses an error?</p><p>If you cannot name a practical check, reduce the task or keep it with a qualified person. A request to “review your own answer” is useful for finding leads, but does not supply independent evidence.</p>`),
 section('trial','Run a bounded trial',`<p>Use the <a href="../downloads/email-brief.txt">delivery brief</a> for a writing trial and the <a href="../guides/verified-weekly-sales-report.html">sales workbook</a> for a numerical trial. Record setup, working time, review, corrections and whether the output passed. Compare complete results rather than the speed of the first response.</p><p>A failed attempt belongs in the log. A second task should test whether the setup is reusable. Avoid extrapolating a small rehearsal into a promise about every employee or every record.</p>`),
 section('result','Write the decision as a condition',`<p>“Use AI for delay-update drafts when facts are supplied, customer details are minimized, and a person checks every promise” is actionable. “Use AI for customer service” leaves the boundary unclear. Keep the condition with the workflow so later users know when to stop.</p>${link('small-team-ai-workflow-audit','Measure a small reporting trial')}`)
 ],[risk]),
 c('check-ai-answers-before-you-trust-them','Audit an AI-style report claim by claim','Classify four claims against an original workbook, then rewrite the draft without unsupported growth or order counts.','Verification',[
 section('draft','Keep the draft and evidence separate',`<p>The practice draft says: “Our weekly report proves sales grew 18%. Nine orders produced RM267.60, and all customer identifiers were preserved.” This deliberately faulty text was authored for the exercise. It is not a recorded output from an AI product.</p>${dl('claim-audit.txt','Download the draft and available evidence')}<p>Open the <a href="../guides/verified-weekly-sales-report.html">worked sales report</a> before deciding which claims can remain. A number matching one cell does not validate the whole paragraph.</p>`),
 section('ledger','Assign a status to each claim',`${table(['Claim','Status','Reason or next check'],[['Sales grew 18%','Unestablished','No prior period or comparable scope supplied'],['Nine orders','Contradicted','Nine lines represent eight distinct orders'],['RM267.60','Supported within scope','Net Shipped sales for the stated week'],['All identifiers preserved','Unestablished from the summary','Inspect source and stored identifier values']])}<p>Unestablished means the available evidence does not settle the claim. It does not mean the statement has been proved false. Keep that distinction when reviewing an unfamiliar answer.</p>`),
 section('rewrite','Write only what the evidence establishes',`<blockquote><p>For 26 October–1 November 2026, the fictional sample contains RM267.60 in net Shipped sales. The report includes 26 units across nine order lines and eight distinct orders.</p></blockquote><p>This authored revision retains the amount and adds its scope. It removes the growth percentage and the preservation claim until their separate checks are completed. If a prior period later becomes available, confirm the same status and date rules before calculating change.</p>`),
 section('reuse','Make the audit reusable',`<p>Keep columns for exact claim, source location, applicable date, status and correction. For a source link, open the supporting passage and verify it covers the statement. A citation to a general overview cannot establish a dataset-specific total.</p><p>Prioritize claims that affect the decision: totals, eligibility conditions, dates, customer promises and permissions. Asking an assistant to identify possible errors can help organize this work, but the evidence and recalculation must still come from outside the draft.</p>${link('source-first-ai-research-workflow','Organize a source ledger')}`)
 ],[gen]),
 c('ai-hallucinations-are-a-workflow-problem','Catch a missing date condition in a plausible sales answer','Use a RM60.00 discrepancy to show how an answer can be wrong even when its formula runs successfully.','Verification',[
 section('counterexample','A valid calculation can answer the wrong question',`<p>The prepared sample contains 13 order lines. Adding every Shipped line produces RM327.60. The requested week, 26 October through before 2 November 2026, produces RM267.60. The RM60.00 difference comes from a RM35.00 line before the window and a RM25.00 line at the excluded end date.</p><p>This missing-condition example was authored for teaching. It does not establish that any particular AI model produced the error.</p>${dl('orders-clean.csv','Download the prepared sample')}`),
 section('trace','Reconcile the difference rather than guessing',`${table(['Item','Amount','Weekly decision'],[['Shipped before 26 October','RM35.00','Exclude'],['Shipped on 2 November','RM25.00','Exclude'],['All Shipped records','RM327.60','Wrong scope for this question'],['Requested week only','RM267.60','Expected result']])}<p>A confident explanation of the first total does not fix its scope. Trace which records enter the calculation and compare them with the stated business question.</p>`),
 section('repair','Turn the scope into explicit tests',`<p>Use an inclusive start, an exclusive end and status exactly Shipped. Check a record on each boundary, a Pending line, a Cancelled line and a legitimate zero-value case. Keep expected outputs before trying a proposed formula.</p><p>The <a href="../tools/weekly-sales-reconciler.html">sales reconciler</a> shows a decision for each source record. Load the fictional sample and inspect the two date exclusions. The workbook provides a second way to check the result.</p>`),
 section('limits','Do not reduce every error to invented facts',`<p>Errors can come from a mistaken task definition, damaged import, source selection, formula condition or generated wording. Identify the stage before changing a prompt. A better prompt cannot recover an identifier already converted to a different value.</p><p>NIST's Generative AI Profile discusses false or inconsistent generated content. This example focuses on a specific numerical check, with no estimate of how often a model fails.</p>${link('check-ai-answers-before-you-trust-them','Audit the resulting report prose')}`)
 ],[gen]),
 c('source-first-ai-research-workflow','Build a source ledger before asking AI to summarize a policy','Compare current, archived, and irrelevant sources using a fictional office-access question.','Verification',[
 section('question','Write a question with a date and scope',`<p>Use this precise question: “For an ordinary visitor on 13 November 2026, what entry time and conditions does the supplied policy establish?” It specifies a person category and a decision date. That prevents a cafeteria schedule or an archived rule from becoming the answer by accident.</p>${dl('policy-source.txt','Download the source pack')}`),
 section('ledger','Record why each source applies',`${table(['Source','Status','Relevant evidence','Use'],[['P1','Superseded 1 October','09:00–18:00','Historical context only'],['P2','Current','10:00–16:00; named host','Governs ordinary visitors'],['P2 exception','Current, conditional','08:00 maintenance visits with approval','Apply only if conditions met'],['P3','Current, different scope','08:00 cafeteria opening','Does not establish access']])}<p>For real research, replace these IDs with direct source links, section names, publication or effective dates and access dates. Keep a short supporting excerpt within permitted quotation limits.</p>`),
 section('draft','Ask for a bounded synthesis',`<p>An authored prompt is: “Answer using only the ledger and source pack. Cite the source ID for each rule. Separate ordinary visitors from maintenance visits. State missing information rather than supplying it from memory.” Review the answer against the pack after generation.</p><p>The accepted ordinary-visitor answer is 10:00–16:00 with a named host. The pack does not answer weekend access or explain how host approval is obtained. Those are follow-up questions for the policy owner.</p>`),
 section('change','Maintain the evidence when sources change',`<p>If a new policy supersedes P2, update its status and revisit answers that rely on it. Keep the previous conclusion with its original date so a later reader can understand why it changed. A source ledger is useful because it exposes these dependencies.</p><p>This teaching case contains no real employment, legal or access advice. For an actual organization, use its authoritative source and approved research process.</p>${link('rag-explained-plain-english','Compare the same case with automated retrieval')}`)
 ]),
 c('what-not-to-share-with-ai-tools','Reduce an order export to the fields needed for a formula question','Create a three-value fictional prompt instead of uploading customer identifiers, phones, and free-text notes.','Privacy',[
 section('scope','Ask what the assistant needs to know',`<p>The sales export has 11 columns, including customer codes, phone numbers and delivery notes. To explain net line value, the required facts are quantity, unit price and the meaning of the discount. Customer contact details contribute nothing to that calculation.</p>${dl('orders-messy.csv','Inspect the fictional source columns')}<p>Even when this site's sample is safe teaching data, the same upload habit may be inappropriate for a real export.</p>`),
 section('minimize','Build a smaller representation',`${table(['Original field','Needed for formula explanation?','Action'],[['quantity','Yes','Use a fictional value of 2'],['unit_price_rm','Yes','Use 12.50'],['discount_rm','Yes','Use 5.00 and state per line'],['phone / customer_code','No','Omit'],['note','No','Omit rather than paraphrase customer details']])}<p>An authored prompt is: “A fictional line has quantity 2, unit price 12.50, and discount 5.00 once per line. Explain gross and net formulas.” The known answers are gross 25.00 and net 20.00.</p>`),
 section('residual','Check what remains after removing names',`<p>Replacing a name with Customer A does not remove an unusual transaction history or a revealing free-text note. Review combinations of details, not just obvious identifiers. A screenshot can also expose other sheets, account information or file paths.</p><p>If the task needs only a schema, share invented column names and values. If it genuinely needs private records, use the organization's approved service and process. A generic checklist cannot determine whether your account or contract permits an upload.</p>`),
 section('alternative','Consider a local calculation first',`<p>The <a href="../tools/weekly-sales-reconciler.html">browser sales tool</a> can calculate this sample without an AI upload endpoint. The live website does load hosting analytics; see the <a href="../privacy.html">privacy disclosure</a>. For sensitive work, use an approved local application and review its environment.</p><p>Write down the minimum input for the task before opening an assistant. That small decision is easier to repeat than cleaning an entire customer record after it has been shared.</p>${link('ai-privacy-checklist-before-you-paste','Apply a task-specific sharing decision')}`)
 ]),
 c('ai-privacy-checklist-before-you-paste','A privacy check for explaining changes between two exports','Decide whether to compare locally, share a summary, or use an approved data service.','Privacy',[
 section('task','The task is an explanation of differences',`<p>Suppose you need a short reconciliation note about two order snapshots. Start by comparing the files with a deterministic method. The assistant writing the explanation may need only reviewed findings, rather than the underlying customer records.</p>${dl('orders-a.csv','Fictional snapshot A')}${dl('orders-b.csv','Fictional snapshot B')}<p>Use <a href="../tools/order-list-comparison.html">order-list comparison</a> with order_id as the key. The expected result is two unchanged keys, one changed key, one only in each file, and one repeated-key group.</p>`),
 section('decision','Choose the smallest input that answers the question',`<p>A sufficient writing brief could say: “One order changed from Pending to Shipped, one key appears only in each snapshot, and one repeated key needs review. Write a neutral reconciliation note. Do not infer refunds, cancellations or missing revenue.” No phone numbers or customer notes are needed.</p>${table(['Proposed input','Decision in this task'],[['Two complete real exports','Unnecessary for wording a reviewed summary'],['Reviewed aggregate findings','Enough for the writing task'],['Fictional reproduction','Useful for debugging a formula'],['Private source needed for analysis','Check approved service, account and policy first']])}`),
 section('check','Inspect both prompt and attachments',`<p>Check hidden sheets, notes, copied email headers and screenshots as well as visible names. Confirm that a file picker selected the intended teaching file. Do not assume a paid account establishes permission to upload workplace data.</p><p>This site cannot inspect your employer's agreements, a service's account settings or the sensitivity of your actual records. If the allowed processing is uncertain, stop the upload and ask the responsible owner.</p>`),
 section('output','Review what the generated note reveals',`<p>An output can disclose sensitive details too. Ensure the intended reader needs the summary and that its claims match the comparison. Keep unresolved repeated keys visible; the comparison does not authorize choosing or deleting a record.</p><p>The site's browser tools process inputs in memory, while hosting analytics receives website metrics. Read the <a href="../privacy.html">current disclosure</a> before using the live tools. An approved desktop application may be a better fit for restricted data.</p>`)
 ]),
 c('write-ai-prompts-that-keep-you-in-control','Write a report prompt with an acceptance test','Turn checked sales figures into a bounded two-sentence update without inventing growth or confusing lines with orders.','Prompting',[
 section('facts','Supply the facts before choosing a tone',`<p>The fictional weekly report has RM267.60 net Shipped sales, 26 units, nine included lines and eight distinct orders for 26 October–1 November 2026. No prior-period total or explanation for demand is supplied.</p><p>An authored prompt is: “Use only these facts. Write two sentences for an operations update. Keep lines and orders distinct. Include the week and Shipped scope. Do not add growth rates, causes or comparisons.” This specification gives the reviewer a concrete result to accept or reject.</p>`),
 section('rubric','Make the checks visible',`${table(['Requirement','Pass condition'],[['Amount','RM267.60, identified as net sales'],['Scope','Shipped, 26 October–1 November 2026'],['Counts','Nine lines across eight orders; 26 units'],['Unsupported claims','No growth, demand cause or invented comparison'],['Format','Two sentences']])}<p>A persuasive tone cannot override any factual check. A reply with correct arithmetic but the wrong order count fails.</p>`),
 section('example','Compare an acceptable authored answer',`<blockquote><p>For 26 October–1 November 2026, the fictional sample recorded RM267.60 in net Shipped sales. It includes 26 units across nine order lines and eight distinct orders.</p></blockquote><p>This is an authored example, not a captured model output. To test an assistant, save the exact response and score each requirement before revising it. If your real reporting convention differs, rewrite the specification and known answer together.</p>`),
 section('reuse','Keep the output contract with the source',`<p>A useful reusable prompt contains fields for purpose, allowed facts, exclusions, output format and acceptance checks. It does not need a fictional expert persona. Use a smaller source when the original contains customer details.</p><p>After an edit, rerun all factual checks. A request to shorten the draft can accidentally remove the reporting window or merge counts. Review the final version that will actually be used.</p>${link('give-ai-feedback-that-improves-drafts','Give targeted feedback when a check fails')}`)
 ]),
 c('prompt-engineering-explained','Specify the row meaning before asking for a spreadsheet formula','Show why “one row is an order line” changes the duplicate rule and the expected report.','Prompting',[
 section('ambiguity','The same words can hide different data models',`<p>“Analyze my orders” leaves open whether each row is an order, an item in an order or a status event. In the fictional sales export, order 000101 has a notebook line and a pen line. Their line IDs differ. Both belong in the report.</p><p>Removing repeated order IDs would discard a legitimate RM9.60 pen line if the notebook row is kept first. Asking for a shorter formula cannot resolve that missing specification.</p>${dl('orders-messy.csv','Download the line-item export')}`),
 section('spec','Write a task contract',`${table(['Field','Specification for this sample'],[['Row meaning','One order line'],['Identity','order_id plus line_id; exact repeated source record investigated separately'],['Dates','Start inclusive; end exclusive'],['Eligible status','Exactly Shipped'],['Money','Quantity × price minus one line discount'],['Checks','Nine included lines, eight orders, RM267.60']])}<p>An authored request can ask an assistant to explain this contract and propose a formula. It should also list required input types and unresolved assumptions before calculating.</p>`),
 section('adversarial','Include a case that breaks the easy answer',`<p>The two-line order exposes the danger of deduplicating by order_id. The exact repeated 000103/1 record exposes the opposite danger of keeping a known accidental repeat. Keep both examples in a test set because they require different decisions.</p><p>Ask for the method's effect on those records. Then inspect the actual output. A statement that “duplicates are handled” is too vague to establish whether the right rows survived.</p>`),
 section('measure','Judge the result after applying it',`<p>Record the prompt, generated formula, input types, output and corrections. A plausible formula is only a candidate until it runs against the known sample. Do not claim a model benchmark from these authored examples.</p><p>The practical work of prompt design here is making the task and failure cases explicit. Once those are clear, a deterministic formula may be sufficient.</p>${link('../guides/duplicate-orders-vs-order-lines','Inspect the duplicate decisions')}`)
 ]),
 c('give-ai-feedback-that-improves-drafts','Correct a draft without losing its accurate parts','Mark a wrong order count and unsupported growth claim, then rerun a five-point review.','Prompting',[
 section('draft','Identify the exact defects',`<p>Consider this authored draft: “The business made RM267.60 from nine orders, showing strong growth.” The amount matches the worked sample, but the count should be eight distinct orders across nine lines. No prior-period evidence establishes growth. The sentence also omits the week and Shipped scope.</p><p>This is a constructed editing exercise, not an observed response from a particular assistant.</p>${dl('claim-audit.txt','Use the practice draft and evidence')}`),
 section('feedback','Give a correction with preserved facts',`<p>Useful feedback is: “Retain RM267.60. State net Shipped sales for 26 October–1 November 2026. Replace nine orders with nine lines across eight distinct orders. Remove the growth claim because no comparison period is supplied. Use two sentences.”</p><p>“Make it more accurate” leaves the required changes implicit. Adding every spreadsheet row would expose more data without improving the writing brief.</p>`),
 section('revision','Check the whole revised message',`<blockquote><p>For 26 October–1 November 2026, the fictional sample generated RM267.60 in net Shipped sales. The report covers nine order lines across eight distinct orders.</p></blockquote>${table(['Check','Result in this authored revision'],[['Amount retained','Pass'],['Lines and orders distinct','Pass'],['Date window supplied','Pass'],['Shipped scope supplied','Pass'],['Unsupported growth removed','Pass']])}<p>The full review matters because a revision can fix one defect and introduce another. If the message later needs units, add the verified 26 units explicitly.</p>`),
 section('stop','Stop when the acceptance checks pass',`<p>Avoid a long loop of tone edits after the message meets its purpose. Each further revision needs another factual pass. Keep the final version beside the source figures so the sender can verify what is being communicated.</p><p>For your own work, save the initial draft, correction instruction, final draft and checklist result. That record shows what changed without pretending every improvement came from a better prompt alone.</p>${link('write-ai-prompts-that-keep-you-in-control','Set acceptance checks before the first draft')}`)
 ]),
 c('use-ai-at-work-without-sounding-generic','Make a delivery update specific without inventing certainty','Replace vague reassurance with a dated estimate, a clear purpose and verified authority.','Everyday work',[
 section('problem','Specificity comes from facts',`<p>“We value your patience and are working tirelessly to resolve this issue” offers little usable information. A useful delay update states which order is involved, what is known, what remains uncertain and the next available step.</p>${dl('email-brief.txt','Use the fictional delivery brief')}<p>Here the carrier estimates 20 November 2026. The writer can communicate status, but cannot promise compensation. Customer name and order reference remain placeholders.</p>`),
 section('edit','Compare the effect of three edits',`${table(['Wording','Problem','Better treatment'],[['It will arrive on 20 November','Turns an estimate into a guarantee','Carrier currently estimates 20 November'],['We will refund you','Authority not supplied','Omit until authorized'],['Your order is important to us','Adds little operational information','State the actual status and available next step']])}<p>A calm tone can be brief. Removing inflated reassurance should not remove an appropriate apology or hide uncertainty.</p>`),
 section('draft','Produce one reviewable message',`<blockquote><p>Hello [name], the carrier currently estimates that order [reference] will arrive on 20 November 2026. The date may change. I’m sorry for the delay; please contact us if you need another status update.</p></blockquote><p>This wording is authored for the exercise. Before sending a real version, verify the estimate, replace placeholders, check the recipient and confirm the sender can provide the stated follow-up.</p>`),
 section('voice','Keep a small style rule',`<p>A team style rule might be: lead with the status, use ordinary words, avoid promises without authority, and include only a next step the team can perform. Test the rule on a cancellation or an absent carrier estimate as well as this easy case.</p><p>When the estimate is missing, say the date is not yet confirmed rather than filling the gap. Useful writing can be honest about an unresolved fact.</p>${link('what-is-generative-ai','Separate generated wording from supplied evidence')}`)
 ]),
 c('ai-meeting-notes-guide','Turn meeting notes into actions without inventing owners','Use a fictional five-statement meeting to distinguish decisions, commitments, proposals and missing assignments.','Everyday work',[
 section('source','Keep the source statement with the action',`<p>The practice notes are from an invented meeting dated 9 November 2026. They contain a decision to use a new export, Dan's commitment to confirm discount meaning by 11 November, an unassigned duplicate review, a possible supplier change and a Friday follow-up.</p>${dl('meeting-source.txt','Download the fictional notes')}${dl('meeting-actions.csv','Download the authored action register')}<p>No recording or real participants were used. The register is an answer key for the exercise.</p>`),
 section('classify','Do not turn a proposal into a decision',`${table(['Statement','Classification','What remains unresolved'],[['Use the new export','Decision','Which reporting week'],['I will confirm by 11 November','Action owned by Dan','No extra deadline needed'],['Someone should check the repeat','Unassigned action','Owner and due date'],['We might switch suppliers','Proposal','No decision recorded'],['Discuss again Friday','Follow-up','Confirm actual calendar date']])}<p>A clean action table with invented owners is less useful than one that exposes missing assignments. Do not give the duplicate review to Mira merely because she raised it.</p>`),
 section('review','Review omissions as well as invented details',`<p>Compare the summary with every source statement. The supplier discussion should remain visible as a proposal, even if the action table contains only tasks. Keep decisions and open questions in separate fields or sections so neither disappears.</p><p>For a real meeting, confirm ambiguous dates and assignments with participants before treating the register as agreed. An AI summary does not establish consent to a recording or approval to share it.</p>`),
 section('followup','Use the register at the next meeting',`<p>Review unresolved fields, confirm completion evidence for Dan's action, and update the export decision when the reporting week is known. Preserve the original statement if a task changes. This prevents a later summary from rewriting what was actually agreed.</p><p>For private meetings, use the approved note-taking process and minimize the material sent to external services. The fictional sample supports practicing the classification without exposing real notes.</p>${link('check-ai-answers-before-you-trust-them','Apply claim-level review to a summary')}`)
 ]),
 c('ai-as-a-learning-tool-not-a-shortcut','Learn SUMIFS by predicting boundary cases first','Use a known-answer sales exercise to test understanding before asking for a formula explanation.','Learning',[
 section('predict','Make a prediction before viewing the answer',`<p>For the prepared sales sample, predict whether three records belong in the week starting 26 October and ending before 2 November 2026: a Shipped line on 26 October, a Shipped line on 2 November, and a Pending line on 1 November. Write the reasons before asking an assistant.</p><p>The first is included, the second is excluded by the end boundary, and the third is excluded by status. This small exercise tests the conditions rather than your ability to copy syntax.</p>${dl('orders-clean.csv','Use the prepared sample')}`),
 section('explain','Ask for a hint at the point of confusion',`<p>An authored study prompt is: “I understand the status criterion but not why the end date uses less-than. Explain it with one included and one excluded date, without writing the whole workbook.” Compare the explanation with the actual boundary records.</p><p>If you want the final formula, ask for a mapping from each criterion to the question it implements. Do not accept “this sums the correct sales” as an explanation of the date logic.</p>`),
 section('transfer','Change one condition and predict the consequence',`${table(['Change','Expected effect'],[['Ignore reporting dates','All Shipped net becomes RM327.60'],['Keep the known exact repeat','Weekly net becomes RM315.60'],['Change Orders G6 from 2 to 3','Weekly net becomes RM280.10'],['Use 2 November as an included end date','The RM25.00 boundary line enters the period']])}<p>The last row describes a changed business question. It is not the original weekly result.</p>`),
 section('check','Explain the result in your own words',`<p>After working through a case, close the explanation and state why each record was included. Then try the second source file with a new date window. A correct first result may come from memorizing the supplied answer; a changed case tests whether the method transferred.</p><p>Keep mistakes in a short learning log: prediction, observed result and corrected rule. Use AI to ask follow-up questions or offer alternative explanations, while the sample and calculation provide the check.</p>${link('../guides/verify-ai-generated-spreadsheet-formulas','Follow the formula-verification exercise')}`)
 ],[['Microsoft: SUMIFS','https://support.microsoft.com/en-us/office/sumifs-function-c9e748f5-7ea7-455d-9406-611cebce642b']]),
 c('how-to-use-ai-without-losing-your-judgment','Keep four decisions visible when AI helps with a report','Separate source meaning, transformation choices, calculation checks and final wording.','Task choice',[
 section('decisions','A report contains decisions before the final sentence',`<p>In the sales example, someone must decide what a row means, whether a repeated record is accidental, which dates and statuses count, and what claims the summary may make. An assistant can help explain those decisions, but silently accepting its assumptions changes the reporting question.</p><p>The source has a legitimate two-line order and a known accidental exact repeat. Treating both as the same kind of duplicate gives the wrong result.</p>`),
 section('record','Keep a short decision record',`${table(['Decision','Rule for the fictional sample','Evidence'],[['Row meaning','One order line','Different line IDs within order 000101'],['Exact repeat','Remove one known accidental record','Data record 5 exactly repeats 4'],['Report scope','Shipped; start included, end excluded','Explicit exercise specification'],['Narrative','No growth or causal claim','No comparison-period evidence']])}<p>Keep the decision record with the workbook. A colleague should be able to reproduce the answer without seeing an AI conversation.</p>`),
 section('disagree','Investigate a conflicting suggestion',`<p>If an assistant suggests deleting all repeated order IDs, inspect the two lines in 000101. The pen line is worth RM9.60 and is genuine within the exercise. This counterexample provides a reason to reject that suggestion.</p><p>If a proposed formula disagrees with RM267.60, compare included records before adjusting the formula to force the target total. Matching a total by accident is not evidence that the row decisions are correct.</p>`),
 section('handover','Hand over the method and its limits',`<p>Record the source file, rule choices, formula or tool version, expected checks and unresolved issues. Explain that the practice workbook covers a fixed prepared range and has no live source connection. A user extending it must update dependent ranges or use a reviewed table-based method.</p><p>The useful role of judgment is choosing and verifying these explicit rules. A polished final paragraph cannot replace them.</p>${link('../guides/verified-weekly-sales-report','Inspect the complete report example')}`)
 ]),
 c('small-team-ai-policy-that-people-follow','Write a one-page rule for AI-assisted customer updates','Define permitted data, draft review, sending authority and failure handling for one concrete team task.','Team practice',[
 section('scope','Write for a task people actually perform',`<p>This fictional team wants help drafting delayed-order updates. A useful rule should tell a staff member what to supply, who reviews the result and what the assistant cannot do. It is an operational example, not legal advice or a compliance certification.</p>${dl('email-brief.txt','Use a sample of the permitted writing brief')}`),
 section('policy','An authored task rule',`${table(['Field','Example team rule'],[['Allowed use','Prepare an unsent delay-update draft'],['Input','Verified carrier estimate and a minimized brief; placeholders for identifiers'],['Service','Only the service and account approved by the organization'],['Review','Sender checks facts, uncertainty, recipient and promises'],['Authority','No refund, compensation, address change or send action without separate authority'],['Failure','Stop if source facts conflict or the action outcome is unknown']])}<p>Name the actual service and responsible role before adopting the rule in a real organization. A placeholder such as “approved tool” is a question to resolve, not an approval by itself.</p>`),
 section('rehearse','Test the rule with three short cases',`<p>First, use the normal brief with an estimated date. Second, remove the estimate: the draft must keep it unresolved. Third, add a request to promise a refund: the writer must obtain authority rather than treating the request as evidence.</p><p>Ask a colleague to follow the rule without coaching. Record where the wording leaves a decision unclear. Improve those parts before expanding the policy to unrelated tasks.</p>`),
 section('maintain','Give maintenance an owner and a trigger',`<p>Assign someone to maintain the approved-service list, record changed account controls and review incidents. Revisit the rule when the task or connected permissions change. Keep a dated change note explaining what staff should do differently.</p><p>Do not collect unnecessary private prompts merely to prove staff followed the policy. Use a minimal record of the task, review outcome and relevant exception, according to the organization's retention rules.</p>${link('ai-agents-explained','Map tool actions to separate permissions')}`)
 ]),
 c('small-team-ai-workflow-audit','Measure whether AI helps a weekly reporting task','Use a blank timing log, a common source and a completion gate instead of assuming a productivity gain.','Team practice',[
 section('target','Agree on the finished result',`<p>Use the original fictional sales export for every method. A completed attempt must preserve identifiers, apply the documented duplicate rule, use the reporting window and produce RM267.60, 26 units, nine included lines and eight orders.</p>${dl('orders-messy.csv','Common source')}${dl('method-comparison.csv','Blank measurement log')}<p>The log intentionally contains no measured times. This article makes no claim that AI is faster.</p>`),
 section('measure','Measure the whole attempt',`${table(['Stage','Include'],[['Setup','Installing or configuring an approved method; learning the source'],['Work','Import, transformation, prompting and calculation'],['Review','Boundary cases, identifier checks and reconciliation'],['Correction','Fixing failed or incomplete output'],['Completion','Whether every agreed output check passed']])}<p>Do not compare an AI first draft with a colleague's fully reviewed report. A fast attempt that fails remains a failed attempt in the record.</p>`),
 section('repeat','Separate setup from repeatable work',`<p>Run a second trial using refresh-next-week.csv and the week starting 2 November. Its expected result is two lines, five units and RM85.00 net. This shows whether the first setup can be reused, rather than requiring the same cleanup again.</p><p>Record experience level and interruptions. Small trials are affected by familiarity and practice order. Rotate methods or repeat the task before treating a difference as a stable saving.</p>`),
 section('decide','Use a conditional conclusion',`<p>A useful conclusion states the tested task, number of attempts, quality gate and actual observed time. If a method only helps draft explanations after calculations are complete, describe that narrower benefit.</p><p>Choose the method with acceptable quality, maintainability and data handling for the task. Keep a small failure case with the workflow so later changes can be checked.</p>${link('../guides/choose-spreadsheet-cleanup-method','Use the detailed comparison procedure')}`)
 ],[risk]),
 c('chatgpt-vs-claude-vs-gemini','Compare AI assistants using one task and an answer key','A blank, reproducible comparison procedure for ChatGPT, Claude, Gemini or another assistant; no invented product ranking.','Task choice',[
 section('scope','Compare a task, not a brand name',`<p>Features, models and account permissions change. This page provides an evaluation procedure rather than a current product ranking. Record the actual product, account type, model if shown, enabled tools, test date and exact task. A result from one setup does not establish every setup's behavior.</p><p>Use the same fictional data and output contract for every assistant. The weekly sales example supplies a known answer without exposing private business records.</p>${dl('orders-messy.csv','Common test input')}${dl('method-comparison.csv','Blank measurement log')}`),
 section('task','Give each assistant the same specification',`<p>State that each row is an order line, that one all-field repeat is deliberately accidental, and that the report covers Shipped lines from 26 October through before 2 November 2026. Require separate line and distinct-order counts. Keep the input, prompt and any follow-up correction with the result.</p>${table(['Criterion','Known answer or review rule'],[['Net / units','RM267.60 / 26'],['Lines / orders','9 / 8'],['Identifiers','Keep their exact text'],['Unsupported claims','No invented growth or demand explanation'],['Reproducibility','Save formula, code or transformation steps']])}`),
 section('score','Score before changing the prompt',`<p>Apply the same quality gate to each first attempt. If a correction is allowed, give comparable correction information and include the time. Record a tool's inability to read a file or execute a formula rather than silently doing that step yourself without accounting for it.</p><p>Separate a helpful explanation from a completed calculation. An assistant may produce useful reasoning while still failing the required output.</p>`),
 section('conclude','Report only what you measured',`<p>Keep failed attempts and repeat with the second source file. Publish a ranking only after actual tests, and scope it to those versions, inputs and criteria. Do not infer accuracy from the length or confidence of an answer.</p><p>No comparative assistant runs were performed for this article. The downloadable log is for your own observations; it is not an empty claim of a completed benchmark.</p>${link('small-team-ai-workflow-audit','Measure work, review and corrections together')}`)
 ])
];
